// Original guided explanations and new application contexts. These checks are
// separate from the older form drills so existing review histories stay intact.
const choice = (prompt, options, answer, translation, why) => ({ prompt, options, answer, sentence: options[answer], translation, why, alternatives: [] });
const fill = (prompt, answer, translation, why, alternatives = []) => ({ prompt, answer,
  sentence: prompt.split(' (')[0].replace('___', answer).replace(/^./, c => c.toUpperCase()), translation, why, alternatives });
const guide = (goal, situation, form, decision, examples, checks, writing) => ({ goal, situation, form, decision,
  examples: examples.map(([sentence, translation, why]) => ({ sentence, translation, why })), checks, writing });
const write = (prompt, model, checklist) => ({ prompt, model, checklist });

